WITH metrics AS (SELECT *, AVG(credit_limit) OVER (PARTITION BY city ORDER BY age, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS credit_limit_avg_6_prior, SUM(age) OVER (PARTITION BY city, country ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_age, SUM(credit_limit) OVER w_part AS running_credit_limit FROM customers WINDOW w_part AS (PARTITION BY city, segment ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT country, segment, ROUND(SUM(running_credit_limit) / NULLIF(COUNT(CASE WHEN segment = 'Corporate' THEN 1 END), 0), 2) AS running_credit_limit_per_corporate, AVG(credit_limit_avg_6_prior) FILTER (WHERE country = 'DE') AS de_avg_credit_limit_avg_6_prior, PERCENTILE_APPROX(running_credit_limit, 0.95) AS running_credit_limit_p95, SUM(CASE WHEN segment = 'Corporate' THEN credit_limit_avg_6_prior ELSE 0 END) AS corporate_credit_limit_avg_6_prior, RANK() OVER (PARTITION BY country ORDER BY AVG(credit_limit_avg_6_prior) FILTER (WHERE country = 'DE') DESC) AS de_avg_credit_limit_avg_6_prior_rank FROM metrics GROUP BY country, segment
